I.append(R(6337610,"आलमंड जॉय हॉट चॉकलेट","मिठाइयों को खास मौकों के लिए बचाकर रखना अच्छा है। इस गरम पेय का आनंद अपने भोजन या नाश्ते के कुछ कार्बोहाइड्रेट की जगह लेकर उठाएँ।","4","1 कप + 2 बड़े चम्मच व्हिप्ड टॉपिंग + 1 बड़ा चम्मच कटे बादाम",
["4 कप बिना चीनी का बादाम दूध","1/4 कप बादाम (कतरे हुए)","1/4 कप कोको पाउडर","1/4 कप कम कैलोरी वाला चीनी का विकल्प","1/2 छोटा चम्मच नारियल एक्स्ट्रैक्ट","1/2 कप व्हिप्ड टॉपिंग (बिना वसा वाली)"],
["बादाम को सूखे सौते पैन में मध्यम-तेज़ आँच पर डालें और हल्का टोस्ट होने तक भूनें। ठंडा होने के लिए एक तरफ़ रख दें।","बादाम दूध, कोको पाउडर, कम या बिना कैलोरी वाला स्वीटनर और नारियल एक्स्ट्रैक्ट को ब्लेंडर में डालें और मिलने और हल्का झागदार होने तक ब्लेंड करें।","हॉट चॉकलेट के मिश्रण को सॉस पैन में डालकर मध्यम आँच पर रखें और उबाल आने दें।","एक कॉफ़ी मग में एक कप हॉट चॉकलेट डालें, ऊपर 2 बड़े चम्मच व्हिप्ड टॉपिंग डालें और 1 बड़ा चम्मच ठंडे, भुने हुए बादाम छिड़कें।","बाकी तीन कॉफ़ी मग के लिए यही दोहराएँ।"]))
I.append(R(6337735,"भूमध्यसागरीय रोल-अप्स","यह रैप एक स्वादिष्ट, लज़ीज़ दोपहर का भोजन है जो एक बढ़िया शाकाहारी विकल्प भी है। सबसे अच्छी बात - इसे 5 मिनट या उससे कम में बनाकर खाने के लिए तैयार किया जा सकता है।","2","1 रोल-अप का 1/2 भाग",
["1 बड़ी साबुत गेहूँ के आटे की टॉर्टिला (10 इंच)","1/4 कप हमस","1/4 कप तैयार तबूले","1 पत्ता रोमेन लेट्यूस (कटा हुआ)","1/2 कप अल्फ़ाल्फ़ा या बीन स्प्राउट्स","1 बड़ा टमाटर (कटा हुआ)"],
["आटे की टॉर्टिला को कटिंग बोर्ड या प्लेट पर सपाट बिछाएँ।","हमस और तबूले को टॉर्टिला के बीच में साथ-साथ एक लंबी पंक्ति में फैलाएँ।","ऊपर रोमेन लेट्यूस डालें।","ऊपर स्प्राउट्स और कटे हुए टमाटर डालें।","रोल करने के लिए तैयार हो जाएँ! लंबी तरफ़ के किनारे से शुरू करके, इसे लपेटें।","इसे आधा काटें और तुरंत आनंद लें या बाद में खाने के लिए प्लास्टिक रैप में कसकर लपेट दें।","वैकल्पिक अतिरिक्त चरण: इसे ऐपेटाइज़र के रूप में खाने के लिए, प्लास्टिक रैप में लपेटें और फ़्रिज में 2–3 घंटे “जमने” दें। प्लास्टिक रैप हटाएँ और आरी जैसी गति से रोल को 1 इंच के टुकड़ों में काटें। कटे हुए हिस्से को ऊपर करके थाली में परोसें।"]))
I.append(R(6337816,"खजूर, बादाम और तिल के लड्डू","हालाँकि ये शानदार ट्रफ़ल जैसे दिखते हैं, ये मीठे व्यंजन ढेर सारे सेहतमंद पोषक तत्वों से भरपूर हैं। खजूर की खेती 5,000 साल से भी ज़्यादा समय से होती आ रही है। यह रेसिपी पहले से बनाई जा सकती है और फ़्रिज में एक सप्ताह तक या फ़्रीज़र में एक महीने तक रखी जा सकती है।","36","1 लड्डू",
["1 पाउंड गुठली रहित खजूर","1/4 कप मक्खन (कमरे के तापमान पर)","1/4 कप पानी","1/2 पाउंड छिले हुए बादाम","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1 छोटा चम्मच पिसी इलायची","1/2 छोटा चम्मच पिसी दालचीनी","1 कप तिल (भुने हुए)","2 बड़े चम्मच पिसे अलसी के बीज"],
["खजूर, मक्खन, पानी, बादाम, वनीला, इलायची और दालचीनी को फ़ूड प्रोसेसर में डालें। चिकना पेस्ट बनने तक पल्स करें। आटे को खजूर के आकार के गोलों में ढालें।","तिल और अलसी के बीज को बेकिंग शीट पर फैलाएँ। खजूर के गोलों को बीजों में लपेटकर लपेट दें। परोसने की थाली में सजाएँ।"]))
I.append(R(6338529,"स्लो कुकर में पकाया पूरा चिकन","क्या आप जानते हैं कि आप पूरा चिकन स्लो कुकर में पका सकते हैं? इस आसान तरीके से नरम, रसदार चिकन बनता है जो पूरे दिन अपने आप पकता रहता है। यह गर्मी के गरम महीनों के लिए एकदम सही है जब आप पूरा चिकन पकाने के लिए घंटों ओवन चालू नहीं रखना चाहते। बस सुबह चिकन चढ़ा दें और रात के खाने तक आपके पास एक स्वादिष्ट चिकन तैयार है! और, आप स्लो कुकर में बचे रस से एक सरल पैन ग्रेवी बना सकते हैं। बचा हुआ चिकन सप्ताह में बाद के झटपट और आसान दोपहर या रात के खाने के लिए रख लें— विचारों के लिए बचे हुए चिकन की आसान रेसिपी का यह संग्रह देखें। और, हड्डियाँ और अंदरूनी अंग (गिब्लेट) बचाकर अपना चिकन शोरबा बनाएँ!","10","3 औंस",
["1 (लगभग 4 पाउंड) पूरा चिकन","2 छोटा चम्मच बिना नमक वाला जड़ी-बूटी मसाला, जैसे Ms. Dash","1 छोटा चम्मच काली मिर्च","1 छोटा चम्मच लहसुन पाउडर"],
["अगर चिकन में अंदरूनी अंग (गिब्लेट) शामिल हैं तो उन्हें निकाल लें (चिकन शोरबा बनाने के लिए उन्हें बचाकर रखें)। चिकन को पेपर टॉवल से थपथपाकर सुखा लें।","एक छोटे कटोरे में मसाले का मिश्रण, काली मिर्च और लहसुन पाउडर मिलाएँ। आधा मसाला चिकन के अंदर छिड़कें। बचा हुआ मसाला चिकन के बाहर लगाएँ।","चिकन को अंडाकार स्लो कुकर में ब्रेस्ट वाला हिस्सा ऊपर करके, या गोल स्लो कुकर में गर्दन वाला हिस्सा ऊपर करके रखें। ढक दें और धीमी सेटिंग पर 8 घंटे पकाएँ।","चिकन को हड्डियों से अलग करें और त्वचा फेंक दें। अभी परोसें, या पके हुए चिकन को 3-5 दिन तक फ़्रिज में रखें।"]))
I.append(R(6338589,"लहसुन में भुना पालक और केल","क्या आप हर रात एक जैसी उबाऊ सब्ज़ियों से थक गए हैं और बदलाव चाहते हैं? क्या आपको पता नहीं कि केल या पालक कैसे पकाएँ? अपने रात के खाने में पौष्टिक जोड़ के लिए यह स्वादिष्ट और आसान व्यंजन आज़माएँ। पत्तेदार सब्ज़ियाँ विटामिन और फ़ाइबर से भरपूर होती हैं, और कैलोरी व कार्बोहाइड्रेट में कम होती हैं।","5","½ कप",
["3 कली लहसुन (बारीक कटा हुआ)","1 1/2 बड़ा चम्मच जैतून का तेल","12 औंस बेबी पालक","8 औंस केल (कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक","4 छोटा चम्मच सेब का सिरका"],
["एक बड़े बर्तन में जैतून का तेल मध्यम-तेज़ आँच पर गरम करें। लहसुन डालें और 30 सेकंड भूनें।","बाकी सामग्री बर्तन में डालें; अच्छी तरह मिलाएँ।","आँच को धीमा करें, ढक दें और 5-7 मिनट पकाएँ।"]))
I.append(R(6338930,"गाजर केक व्हूपी पाई","यह खास मौकों पर आनंद लेने के लिए एक लज़ीज़ व्यंजन है। इसमें तो ताज़ी गाजर भी बेक की गई है!","12","1 व्हूपी पाई",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 कप ब्राउन शुगर का विकल्प","1/2 कप बिना चीनी की एप्पलसॉस","1/4 कप जैतून का तेल","1/2 कप अंडे का विकल्प","2 छोटा चम्मच वनीला एक्स्ट्रैक्ट (बाँटकर उपयोग करें)","1 कप साबुत गेहूँ का आटा","1 कप पुराने ढंग के रोल्ड ओट्स","2 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच बेकिंग सोडा","1 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल","2 कप कद्दूकस की हुई गाजर","8 औंस बिना वसा वाला क्रीम चीज़","2 बड़े चम्मच मेपल सिरप","2 बड़े चम्मच कम कैलोरी वाला दानेदार चीनी का विकल्प (जैसे Truvia)","1 छोटा चम्मच नींबू का रस"],
["ओवन को 350°F पर पहले से गरम करें। दो बेकिंग शीट पर बेकिंग पेपर बिछाएँ और कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","एक मध्यम कटोरे में ब्राउन शुगर का मिश्रण, एप्पलसॉस, तेल, अंडे का विकल्प और वनीला मिलाएँ। अच्छी तरह मिलाएँ और एक तरफ़ रख दें।","एक बड़े कटोरे में आटा, ओट्स, बेकिंग पाउडर, बेकिंग सोडा, दालचीनी और जायफल मिलाएँ।","सूखी सामग्री के बीच में गड्ढा बनाएँ। चीनी वाला (गीला) मिश्रण एक साथ सूखी सामग्री में डालें और अच्छी तरह मिलाएँ।","गाजर मिलाएँ। ढेर लगे बड़े चम्मच के आकार के घोल के ढेर बेकिंग शीट पर रखें। उन्हें लगभग 2 इंच की दूरी पर रखें, कुल 24 कुकीज़ के लिए (12-12 की 2 शीट)।","15 मिनट बेक करें। ठंडा होने के लिए एक तरफ़ रख दें।","एक छोटे कटोरे में भरावन की सामग्री को चिकना और फूला होने तक फेंटें। दो कुकीज़ के बीच फ्रॉस्टिंग की हल्की परत लगाएँ।"]))
I.append(R(6340387,"कैरामलाइज़ प्याज़ के साथ रसीला सैल्मन","अविवा गोल्डफ़ार्ब कहती हैं: मेरी दोस्त और पड़ोसी क्रिस्टीन डैलेयर ने यह शानदार रेसिपी साझा की। आप इसे एक शानदार डिनर पार्टी या किसी खास पारिवारिक रात्रिभोज में परोस सकते हैं। इसे पके हुए फ़ारो और नींबू व लहसुन वाली हरी फलियों के साथ परोसें। स्वाद बढ़ाने वाले सुझाव: सोआ दोगुना करें और मसाले के मिश्रण में 1/4 छोटा चम्मच बिना नमक वाला नींबू-काली मिर्च मसाला डालें। सैल्मन को ताज़े नींबू की फाँकों के साथ परोसें।","4","3 औंस सैल्मन + 2 बड़े चम्मच प्याज़",
["1 पाउंड सैल्मन, सॉकआई","1/2 मध्यम नींबू (ऊपर से नीचे आधा काटा और पतला कटा हुआ)","1/8 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच सूखा सोआ","1/4 छोटा चम्मच पिसी अदरक","1/2 मध्यम मीठा प्याज़ (ऊपर से नीचे आधा काटा और पतला कटा हुआ)","1 बड़ा चम्मच जैतून का तेल"],
["ओवन को 350° F पर पहले से गरम करें। एक बड़ी, भारी, ओवन में रखने योग्य कड़ाही में जैतून का तेल मध्यम आँच पर गरम करें और प्याज़ डालें। बीच-बीच में चलाते हुए सुनहरा होने तक 8 से 10 मिनट पकाएँ।","इस बीच, एक छोटे कटोरे में अदरक, सोआ, नमक और काली मिर्च मिलाएँ; एक तरफ़ रख दें। प्याज़ के ऊपर नींबू के स्लाइस और फिर सैल्मन रखें, और सैल्मन के ऊपर मसाले बराबर छिड़कें। कड़ाही को ओवन में रखें और सैल्मन को लगभग 20 मिनट, पूरी तरह पकने तक पकाएँ। ओवन से निकालें और तुरंत परोसें। नींबू और लहसुन वाली हरी फलियाँ सैल्मन के साथ बढ़िया साइड डिश बनती हैं।","स्लो कुकर के निर्देश: सैल्मन फ़िलेट को ऐसे टुकड़ों में काटें जो स्लो कुकर में आ जाएँ। प्याज़ को स्लो कुकर की तली में रखें। सैल्मन के हर टुकड़े को अलग एल्युमिनियम फ़ॉइल के टुकड़े पर रखें जो पैकेट में मोड़ने के लिए पर्याप्त बड़ा हो। मसाले सैल्मन के टुकड़ों पर बराबर छिड़कें और ऊपर नींबू के स्लाइस रखें। फ़ॉइल को पैकेट में मोड़ें, और पैकेट को स्लो कुकर में प्याज़ के ऊपर रखें, ज़रूरत हो तो एक के ऊपर एक रखकर। धीमी आँच पर 6 से 8 घंटे या तेज़ आँच पर 3 से 4 घंटे पकाएँ (पतले फ़िलेट के लिए पकने की जाँच जल्दी करें)। सैल्मन को पैकेट से निकालें, फिर परोसने से पहले ऊपर प्याज़ डालें।"]))
I.append(R(6341327,"स्ट्रॉबेरी और बादाम के साथ ओके ओटमील","ओटमील में थोड़ा सा फलों का जैम, ताज़ी स्ट्रॉबेरी और बादाम मिलाकर उसे एक नया रूप दें।","4","½ कप ओटमील + 1 बड़ा चम्मच फल का स्प्रेड + ½ कप बेरियाँ + 1 बड़ा चम्मच बादाम",
["1 कप पुराने ढंग के रोल्ड ओट्स (ग्लूटेन-फ़्री)","2 कप पानी","1/4 छोटा चम्मच कोशर नमक","3 बड़े चम्मच रसभरी फल स्प्रेड (हल्का पिघलाया हुआ)","1/2 छोटा चम्मच बादाम एक्स्ट्रैक्ट","2 कप स्ट्रॉबेरी (चार भागों में कटी हुई)","1 औंस पतले कटे बादाम (भुने हुए)"],
["पानी, ओट्स और नमक को एक मध्यम आकार के पैन में मिलाएँ। उबाल आने दें, आँच कम करें और बिना ढके 10 मिनट धीमी आँच पर पकाएँ। आँच से हटाएँ और 2 मिनट रखा रहने दें।","फल के स्प्रेड को एक छोटे माइक्रोवेव-सुरक्षित कटोरे में रखें और तेज़ सेटिंग पर 15 सेकंड या हल्का पिघलने तक पकाएँ। आँच से हटाएँ और एक्स्ट्रैक्ट मिलाएँ।","ओटमील को बराबर मात्रा में 4 कटोरों में चम्मच से डालें। ऊपर 1 बड़ा चम्मच फल का स्प्रेड, 1/2 कप बेरियाँ और 1 बड़ा चम्मच बादाम डालें।"]))
I.append(R(6342617,"तीखा लहसुन-अदरक चिकन","यह झटपट, आसान, बिना झंझट वाला व्यंजन गरम, तीखा और भरपूर स्वाद से भरा है। आप गरम मिर्च सॉस की मात्रा बदलकर तीखेपन को ठीक कर सकते हैं।","4","1 ½ कप",
["2 बड़े चम्मच कैनोला तेल","2 इंच ताज़ी अदरक (छिली और बारीक कटी हुई)","2 कली लहसुन (छिली और कटी हुई)","16 औंस चिकन ब्रेस्ट (बिना हड्डी, बिना त्वचा, स्टिर-फ़्राई के लिए कटे हुए)","16 औंस बेबी बोक चॉय (धुली और चार भागों में कटी हुई)","1 मध्यम लाल शिमला मिर्च (बीज निकाली और पतली कटी हुई)","1 कप हरी प्याज़ (कटी हुई)","1 कप शोरबा (कम सोडियम वाला, सब्ज़ी या चिकन)","2 छोटा चम्मच सोया सॉस (कम सोडियम वाला)","2 छोटा चम्मच गरम मिर्च सॉस","2/3 कप ताज़ी धनिया पत्ती (कटी हुई)","2 कप पका हुआ ब्राउन राइस"],
["कैनोला तेल को वोक या बड़ी सौते पैन में डालें। अदरक डालें और सुगंध आने तक पकाएँ। लहसुन और चिकन डालें और चिकन के पारदर्शी न रहने तक स्टिर-फ़्राई करें।","बोक चॉय, शिमला मिर्च और हरी प्याज़ डालें और बोक चॉय के मुरझाना शुरू होने तक पकाएँ।","शोरबा, सोया सॉस, मिर्च सॉस और धनिया पत्ती डालें। गरम और अच्छी तरह मिलने तक स्टिर-फ़्राई करें। ब्राउन राइस के ऊपर परोसें।"]))
I.append(R(6342815,"हरी फलियों के “फ़्राइज़”","ये कम वसा वाले हरी फलियों के “फ़्राइज़” अपनी सब्ज़ियों का आनंद लेने का एक मज़ेदार और स्वादिष्ट तरीका हैं। ताज़ी हरी फलियों पर लेप लगाकर बाहर से कुरकुरी और अंदर से नरम होने तक बेक किया जाता है। ये एक बढ़िया नाश्ता या साइड डिश हैं जो सरल और संतोषजनक दोनों हैं।","5","लगभग 8 फ़्राइज़",
["8 औंस ताज़ी हरी फलियाँ (सिरे कटे हुए)","1 बड़ा अंडा","1 बड़े अंडे का सफ़ेद भाग","1/8 छोटा चम्मच हॉट सॉस (स्वादानुसार)","1/2 कप कॉर्नमील","1/2 छोटा चम्मच लहसुन नमक","1/8 छोटा चम्मच काली मिर्च","2 बड़े चम्मच परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ)"],
["ओवन को 425 डिग्री F पर पहले से गरम करें।","एक उथली प्लेट में पूरे अंडे, अंडे के सफ़ेद भाग और हॉट सॉस को फेंटकर मिलाएँ।","दूसरी उथली प्लेट में कॉर्नमील, लहसुन नमक, काली मिर्च और परमेसन को मिलाएँ।","हर हरी फली को अंडे के मिश्रण में डुबोएँ और फिर कॉर्नमील के मिश्रण में हल्का लपेटें।","हरी फलियों को बेकिंग शीट पर रखें और हल्का सुनहरा होने तक 25 मिनट बेक करें। अपनी पसंदीदा डिपिंग सॉस के साथ परोसें।"]))
I.append(R(6344459,"पीकन, 1 औंस","पीकन की पोषण संबंधी जानकारी","1","1 औंस",["1 औंस पीकन"],[]))
I.append(R(6345604,"चॉकलेट अखरोट मग केक","जब आपको मिठाई चाहिए हो, तो कॉफ़ी मग के अंदर बना यह केक नियंत्रित मात्रा में मिठाई का आनंद लेने का एक बढ़िया तरीका है।","1","1 मग केक",
["2 बड़े चम्मच बिना चीनी का कोको पाउडर","2 बड़े चम्मच सफ़ेद साबुत गेहूँ का आटा","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/4 छोटा चम्मच बेकिंग पाउडर","1 चुटकी नमक","1 1/2 छोटा चम्मच स्टीविया पाउडर","1 1/2 छोटा चम्मच कैनोला तेल","2 बड़े चम्मच स्किम मिल्क","1/4 छोटा चम्मच वनीला एक्स्ट्रैक्ट","3/4 बड़ा चम्मच अखरोट (कटे हुए)"],
["कॉफ़ी मग पर कुकिंग स्प्रे करें।","आटा, कोको पाउडर, बेकिंग पाउडर, नमक, स्टीविया, कैनोला तेल, दूध और वनीला डालें और मिलाने के लिए चलाएँ।","45 सेकंड माइक्रोवेव करें।","ऊपर अखरोट डालें और परोसें।"]))
I.append(R(6345810,"ब्रसल्स स्प्राउट्स स्लॉ","यह रेसिपी एक दिन (या कई घंटे) पहले बनाना सबसे अच्छा है ताकि ब्रसल्स स्प्राउट्स ड्रेसिंग को अच्छी तरह सोख लें, लेकिन ज़रूरत हो तो इसे तुरंत भी परोसा जा सकता है।","9","1/2 कप",
["6 कप पानी","1 पाउंड ताज़े ब्रसल्स स्प्राउट्स","2 डंठल हरी प्याज़ (बारीक कटी हुई)","1/4 कप राइस वाइन सिरका","1 बड़ा चम्मच डिजॉन सरसों","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","2 बड़े चम्मच कम कैलोरी वाला चीनी का विकल्प","1/4 कप लाइट मेयोनेज़","1/4 छोटा चम्मच काली मिर्च","1/2 कप पतले कटे बादाम (भुने हुए)"],
["एक बड़े बर्तन में 6 कप पानी उबालें। ब्रसल्स स्प्राउट्स डालें और उबलते पानी में 1 मिनट ब्लांच करें। उबलते पानी से निकालें और पकना रोकने के लिए ठंडे पानी के नीचे धोएँ। स्प्राउट्स को साफ़ तौलिये से सुखा लें।","ब्रसल्स स्प्राउट्स का डंठल काटें और लंबाई में आधा काटें। फ़ूड प्रोसेसर के स्लाइसिंग ब्लेड से ब्रसल्स स्प्राउट्स को कद्दूकस करने के लिए प्रोसेस करें। आप यह बॉक्स ग्रेटर के स्लाइसिंग वाले हिस्से या बहुत तेज़ चाकू से भी कर सकते हैं।","एक मध्यम कटोरे में हरी प्याज़, सिरका, सरसों, सोया सॉस, कम या बिना कैलोरी वाला स्वीटनर, मेयोनेज़ और काली मिर्च को फेंटकर मिलाएँ।","कद्दूकस किए ब्रसल्स स्प्राउट्स और भुने बादाम को ड्रेसिंग में डालें और अच्छी तरह मिलाएँ।"]))
save(4,I)
